import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validates successful user registration by supplying a unique and valid email
 * address and a compliant password.
 *
 * Ensures the user is created and the returned data includes a unique user ID,
 * email, creation timestamp, and valid JWT tokens. Checks that fields meet
 * schema requirements and returned authentication context matches
 * specifications.
 *
 * Steps:
 *
 * 1. Generate a unique and valid email address and a password that meets
 *    complexity rules.
 * 2. Register a user via api.functional.auth.user.join().
 * 3. Validate that the API response satisfies ITodoListUser.IAuthorized using
 *    typia.assert().
 * 4. Assert that all relevant fields are present: id (uuid), email, locked (should
 *    be false), created_at (date-time), updated_at (date-time), deleted_at
 *    (should be null or undefined), token (with valid access/refresh, date-time
 *    fields).
 * 5. Check email is the same as requested, and the returned id is a valid uuid.
 * 6. Validate that JWT tokens are non-empty strings, with correct expiration
 *    formats.
 */
export async function test_api_user_registration_success(
  connection: api.IConnection,
) {
  // Step 1: Generate valid registration data
  const email = typia.random<
    string & tags.Format<"email"> & tags.MinLength<3> & tags.MaxLength<255>
  >();
  const password = RandomGenerator.alphaNumeric(10) + "Aa1"; // Ensure minimum length & complexity (letters and numbers)
  const requestBody = {
    email,
    password: password satisfies string &
      tags.MinLength<8> &
      tags.MaxLength<72> &
      tags.Format<"password">,
  } satisfies ITodoListUser.ICreate;

  // Step 2: Register the user
  const output = await api.functional.auth.user.join(connection, {
    body: requestBody,
  });

  // Step 3: Validate API response type and structure
  typia.assert<ITodoListUser.IAuthorized>(output);

  // Step 4: Validate returned fields
  // Validate id is correct UUID
  TestValidator.predicate(
    "output.id is valid uuid",
    typeof output.id === "string" && output.id.length > 0,
  );
  // Validate email matches requested email
  TestValidator.equals("output.email matches input email", output.email, email);
  // Validate account is not locked
  TestValidator.equals(
    "output.locked is false for new account",
    output.locked,
    false,
  );
  // Validate created_at/updated_at looks like date-time
  TestValidator.predicate(
    "output.created_at is non-empty date-time string",
    typeof output.created_at === "string" && output.created_at.length > 0,
  );
  TestValidator.predicate(
    "output.updated_at is non-empty date-time string",
    typeof output.updated_at === "string" && output.updated_at.length > 0,
  );
  // Validate deleted_at is null or undefined
  TestValidator.equals(
    "output.deleted_at is null or undefined for active user",
    output.deleted_at ?? null,
    null,
  );

  // Step 5: Validate returned token fields
  const token = output.token;
  typia.assert<IAuthorizationToken>(token);
  TestValidator.predicate(
    "token.access is non-empty",
    typeof token.access === "string" && token.access.length > 0,
  );
  TestValidator.predicate(
    "token.refresh is non-empty",
    typeof token.refresh === "string" && token.refresh.length > 0,
  );
  TestValidator.predicate(
    "token.expired_at is non-empty date-time",
    typeof token.expired_at === "string" && token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "token.refreshable_until is non-empty date-time",
    typeof token.refreshable_until === "string" &&
      token.refreshable_until.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test that user registration prevents duplicate emails.
 *
 * 1. Register a user with a random unique email and valid password.
 * 2. Attempt to register another user with the same email but a different valid
 *    password.
 * 3. Expect the second registration to fail due to unique email constraint.
 * 4. Ensure no type errors or invalid requests are sent.
 */
export async function test_api_user_registration_duplicate_email_rejection(
  connection: api.IConnection,
) {
  // 1. Register a user with a unique, valid email and valid password
  const registrationData = {
    email: typia.random<
      string & tags.MinLength<3> & tags.MaxLength<255> & tags.Format<"email">
    >(),
    password: typia.random<
      string & tags.MinLength<8> & tags.MaxLength<72> & tags.Format<"password">
    >(),
  } satisfies ITodoListUser.ICreate;

  const user1: ITodoListUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: registrationData },
  );
  typia.assert(user1);
  TestValidator.equals(
    "registered user email matches input",
    user1.email,
    registrationData.email,
  );

  // 2. Attempt to register another user with the same email but new valid password
  const registrationDataDup = {
    email: registrationData.email,
    password: typia.random<
      string & tags.MinLength<8> & tags.MaxLength<72> & tags.Format<"password">
    >(),
  } satisfies ITodoListUser.ICreate;

  await TestValidator.error(
    "should reject duplicate user registration with same email",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: registrationDataDup,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validates user login with correct credentials after registration.
 *
 * 1. Register a new user account (with random, valid email and password).
 * 2. Attempt to login using those same credentials, supplying a random
 *    href/referrer.
 * 3. Assert the login response includes a valid access/refresh token pair, correct
 *    user id/email, locked=false, and correct timestamps (created_at,
 *    updated_at present, deleted_at null/undefined).
 * 4. Assert all returned fields match those from registration and business rules
 *    (active user, not locked or deleted, timestamps present).
 */
export async function test_api_user_login_success(connection: api.IConnection) {
  // 1. Register a new user
  const email = typia.random<
    string & tags.MinLength<3> & tags.MaxLength<255> & tags.Format<"email">
  >();
  const password = typia.random<
    string & tags.MinLength<8> & tags.MaxLength<72> & tags.Format<"password">
  >();
  const createBody = {
    email,
    password,
  } satisfies ITodoListUser.ICreate;
  const registered = await api.functional.auth.user.join(connection, {
    body: createBody,
  });
  typia.assert(registered);

  // 2. Login with correct credentials (using random href/referrer)
  const loginBody = {
    email: email as string & tags.Format<"email">,
    password: password as string & tags.Format<"password">,
    // Both URIs, required per DTO definition
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoListUser.ILogin;
  const loggedIn = await api.functional.auth.user.login(connection, {
    body: loginBody,
  });
  typia.assert(loggedIn);

  // 3. Assert JWT tokens, user metadata, and session correctness
  TestValidator.equals("user id matches", loggedIn.id, registered.id);
  TestValidator.equals("user email matches", loggedIn.email, email);
  TestValidator.equals("locked is false", loggedIn.locked, false);
  TestValidator.equals(
    "deleted_at is null or undefined",
    loggedIn.deleted_at,
    null,
  );
  TestValidator.predicate(
    "created_at is ISO date-time",
    typeof loggedIn.created_at === "string" && loggedIn.created_at.length > 10,
  );
  TestValidator.predicate(
    "updated_at is ISO date-time",
    typeof loggedIn.updated_at === "string" && loggedIn.updated_at.length > 10,
  );

  typia.assert<IAuthorizationToken>(loggedIn.token);
  TestValidator.predicate(
    "access token non-empty",
    typeof loggedIn.token.access === "string" &&
      loggedIn.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token non-empty",
    typeof loggedIn.token.refresh === "string" &&
      loggedIn.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "expired_at present",
    typeof loggedIn.token.expired_at === "string" &&
      loggedIn.token.expired_at.length > 10,
  );
  TestValidator.predicate(
    "refreshable_until present",
    typeof loggedIn.token.refreshable_until === "string" &&
      loggedIn.token.refreshable_until.length > 10,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Ensures the login attempt fails when the password provided is incorrect,
 * while the email exists.
 *
 * Business context:
 *
 * - Verifies the authentication system securely rejects login with a valid email
 *   but wrong password.
 * - Ensures that no sensitive information is leaked when login fails (e.g.,
 *   system does not reveal which credential is incorrect).
 * - Only error occurrence is validated—not error message or HTTP status code.
 *
 * Steps:
 *
 * 1. Register a new user with valid random credentials.
 * 2. Attempt to log in to that email with a wrong password but valid context
 *    fields.
 * 3. Assert that authentication fails, and an error is thrown without examining
 *    the message.
 */
export async function test_api_user_login_failure_wrong_password(
  connection: api.IConnection,
) {
  // 1. Register a new user.
  const registrationBody = {
    email: typia.random<
      string & tags.MinLength<3> & tags.MaxLength<255> & tags.Format<"email">
    >(),
    password: typia.random<
      string & tags.MinLength<8> & tags.MaxLength<72> & tags.Format<"password">
    >(),
  } satisfies ITodoListUser.ICreate;
  const user = await api.functional.auth.user.join(connection, {
    body: registrationBody,
  });
  typia.assert(user);

  // 2. Attempt login with correct email, wrong password, valid context.
  const loginBody = {
    email: registrationBody.email,
    password: typia.random<
      string & tags.MinLength<8> & tags.MaxLength<72> & tags.Format<"password">
    >(), // intentionally wrong
    href: "https://todolist.example.com/login",
    referrer: "https://todolist.example.com/",
  } satisfies ITodoListUser.ILogin;

  await TestValidator.error(
    "login with wrong password should be rejected",
    async () => {
      await api.functional.auth.user.login(connection, { body: loginBody });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Verifies user login failure for an unregistered email address.
 *
 * This test ensures the authentication endpoint does not allow login attempts
 * with an email address that is not associated with any user account. The
 * endpoint must respond securely with a generic error response and must not
 * issue any JWT token or success info. This supports best practices against
 * account enumeration and credential stuffing attacks.
 *
 * Steps:
 *
 * 1. Prepare valid but unregistered email and valid password
 * 2. Submit login attempt with realistic audit/session fields (`href`, `referrer`)
 * 3. Assert that the API rejects the login with a business error, no token is
