    searchStatusPending.pagination.current,
    1,
  );
  TestValidator.equals(
    "zero records for new user",
    searchStatusPending.pagination.records,
    0,
  );
  TestValidator.equals(
    "zero total pages for new user",
    searchStatusPending.pagination.pages,
