    await api.functional.auth.admin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(createdAdmin);

  // 2. (Implicit authentication handled by SDK after join)
  TestValidator.equals(
    "admin email matches join input",
    createdAdmin.email,
    adminJoinBody.email,
  );

