    string & tags.Format<"uuid">
  >();
  await TestValidator.error(
    "delete with non-existent adminId must fail",
    async () => {
      await api.functional.todoList.admin.admins.erase(connection, {
        adminId: randomNonExistentId,
      });
    },
  );
}

