import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminLogin(props: {
  body: ITodoListAdmin.ILogin;
}): Promise<ITodoListAdmin.IAuthorized> {
  // 1. Find admin by email and not deleted
  const admin = await MyGlobal.prisma.todo_list_admins.findFirst({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
  });
  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }
  // 2. Account locked check
  if (admin.locked === true) {
    throw new HttpException("Account locked", 401);
  }
  // 3. Password hash verification
  const passwordValid = await PasswordUtil.verify(
    props.body.password,
    admin.password_hash,
  );
  if (!passwordValid) {
    throw new HttpException("Invalid credentials", 401);
  }
  // 4. Create new admin session with required fields as empty strings
  const sessionId = v4();
  const now = new Date();
  const accessExpiration = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpiration = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.todo_list_admin_sessions.create({
    data: {
      id: sessionId,
      admin_id: admin.id,
      created_at: toISOStringSafe(now),
      expired_at: toISOStringSafe(accessExpiration),
      ip: "",
      href: "",
      referrer: "",
    },
  });
  // 5. Generate JWT tokens
  const token = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpiration),
    refreshable_until: toISOStringSafe(refreshExpiration),
  };
  // 6. Compose response
  return {
    id: admin.id,
    email: admin.email,
    locked: !!admin.locked,
    role: admin.role,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    deleted_at:
      admin.deleted_at === null ? undefined : toISOStringSafe(admin.deleted_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserRefresh(props: {
  body: ITodoListUser.IRefresh;
}): Promise<ITodoListUser.IAuthorized> {
  let decoded: { id: string; session_id: string; type: "user" };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "user" };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "user") {
    throw new HttpException("Invalid token type", 403);
  }

  // Retrieve the session (by session id)
  const session = await MyGlobal.prisma.todo_list_user_sessions.findFirst({
    where: { id: decoded.session_id },
  });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  // Fetch the user info; user_id is the foreign key on the session row
  const user = await MyGlobal.prisma.todo_list_users.findUnique({
    where: { id: session.user_id },
  });
  if (!user) {
    throw new HttpException("Account does not exist", 404);
  }
  if (user.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  // Calculate expirations
  const accessExpiresValue = Date.now() + 60 * 60 * 1000;
  const refreshExpiresValue = Date.now() + 7 * 24 * 60 * 60 * 1000;
  const accessExpires = toISOStringSafe(new Date(accessExpiresValue));
  const refreshExpires = toISOStringSafe(new Date(refreshExpiresValue));

  // Generate new tokens
  const access = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const refresh = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  await MyGlobal.prisma.todo_list_user_sessions.update({
    where: { id: session.id },
    data: { expired_at: refreshExpires },
  });

  return {
    id: user.id,
    email: user.email,
    locked: user.locked,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at !== null ? toISOStringSafe(user.deleted_at) : undefined,
    token: {
      access: access,
      refresh: refresh,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    },
  };
}

